import React from "react";
import { useNavigate } from "react-router-dom";

const Home = ({ setVisitedHome }) => {
  const navigate = useNavigate();

  const handleStart = () => {
    setVisitedHome(true);
    navigate("/interview");
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-[80vh] text-center px-6">
      <h1 className="text-5xl font-bold mb-4 text-blue-100">Welcome to AI Interview Coach</h1>
      <p className="text-blue-300 mb-6 max-w-2xl">
        Get personalized feedback on your interview performance using advanced AI.
      </p>
      <button
        onClick={handleStart}
        className="bg-blue-600 px-8 py-3 rounded-md text-white font-semibold hover:bg-blue-700 transition"
      >
        Start Interview
      </button>
    </div>
  );
};

export default Home;
